		player[9][3] = player[9][3] or {}
			player[9][3][6] = { 7466, 104, 133, 2351 }
	end
end
if coolstats and coolstats.MarkUwUDataRaidLayerLoaded then
	coolstats.MarkUwUDataRaidLayerLoaded(coolstatsUwUData, layerKey, chunkStartIndex)
end
